//go:build ignore
package main
import("encoding/json";"fmt";"os";"path/filepath";"sort";"strings";"time";"unicode";"unicode/utf8")
const PAGE_SIZE=10
const SCHEMA_VERSION=2
const RECENT_N=10
func main(){inputFile:="wenzhang.json";outputDir:="articles";if err:=os.MkdirAll(outputDir,0755);err!=nil{fmt.Fprintf(os.Stderr,"创建目录失败: %v\n",err);os.Exit(1)};raw,err:=os.ReadFile(inputFile);if err!=nil{if os.IsNotExist(err){fmt.Println("未找到 wenzhang.json，跳过拆分");os.Exit(0)};fmt.Fprintf(os.Stderr,"读取文件失败: %v\n",err);os.Exit(1)};var data map[string]interface{};if err:=json.Unmarshal(raw,&data);err!=nil{fmt.Fprintf(os.Stderr,"wenzhang.json 格式错误\n");os.Exit(1)};announcements,ok:=data["announcements"].([]interface{});if!ok{announcements=[]interface{}{}};var rawArticles []map[string]interface{};for idx,item:=range announcements{article,ok:=item.(map[string]interface{});if!ok{continue};na:=make(map[string]interface{});for k,v:=range article{na[k]=v};na["id"]=idx;if av,ex:=na["all"];ex{na["all"]=normalizeAll(av)};rawArticles=append(rawArticles,na)};var articles []map[string]interface{};deletedCount:=0;for _,a:=range rawArticles{if del,ok:=a["delete"];ok{if db,ok:=del.(bool);ok&&db{deletedCount++;continue}};articles=append(articles,a)};if len(articles)==0{fmt.Println("没有文章，跳过拆分");os.Exit(0)};sorted:=make([]map[string]interface{},len(articles));copy(sorted,articles);sort.Slice(sorted,func(i,j int)bool{return getStringField(sorted[i],"date","1970-01-01")>getStringField(sorted[j],"date","1970-01-01")});total:=len(sorted);totalPages:=(total+PAGE_SIZE-1)/PAGE_SIZE;var pageIndex []map[string]interface{};var pageFiles []string;for p:=1;p<=totalPages;p++{start:=(p-1)*PAGE_SIZE;end:=start+PAGE_SIZE;if end>total{end=total};pd:=map[string]interface{}{"total":total,"totalPages":totalPages,"page":p,"list":sorted[start:end]};fn:=filepath.Join(outputDir,fmt.Sprintf("page-%d.json",p));if err:=writeJSON(fn,pd);err!=nil{fmt.Fprintf(os.Stderr,"写入 %s 失败: %v\n",fn,err);os.Exit(1)};fmt.Printf("生成 page-%d.json (%d 篇)\n",p,end-start);pageFiles=append(pageFiles,fmt.Sprintf("page-%d.json",p));sid,eid:=0,0;if end>start{sid,_=sorted[start]["id"].(int);eid,_=sorted[end-1]["id"].(int)};pageIndex=append(pageIndex,map[string]interface{}{"page":p,"file":fmt.Sprintf("page-%d.json",p),"count":end-start,"startId":sid,"endId":eid})};ad:=map[string]interface{}{"total":total,"list":sorted};if err:=writeJSON(filepath.Join(outputDir,"all.json"),ad);err!=nil{fmt.Fprintf(os.Stderr,"写入 all.json 失败: %v\n",err);os.Exit(1)};fmt.Printf("生成 all.json (%d 篇)\n",total);al:=make([]map[string]interface{},0,total);for _,a:=range sorted{al=append(al,map[string]interface{}{"id":a["id"],"title":getStringField(a,"title","无标题"),"date":getStringField(a,"date","1970-01-01"),"tags":getTagsField(a),"all":getAllField(a)})};arc:=map[string]interface{}{"total":total,"list":al};if err:=writeJSON(filepath.Join(outputDir,"archive.json"),arc);err!=nil{fmt.Fprintf(os.Stderr,"写入 archive.json 失败: %v\n",err);os.Exit(1)};fmt.Printf("生成 archive.json (%d 篇，无正文，保留 all)\n",total);var articleIndex []map[string]interface{};var articleFiles []string;for _,article:=range sorted{idVal,ok:=article["id"].(int);if!ok{continue};fn:=fmt.Sprintf("article-%d.json",idVal);if err:=writeJSON(filepath.Join(outputDir,fn),article);err!=nil{fmt.Fprintf(os.Stderr,"写入 %s 失败: %v\n",fn,err);os.Exit(1)};articleIndex=append(articleIndex,map[string]interface{}{"id":idVal,"file":fn});articleFiles=append(articleFiles,fn)};fmt.Printf("生成 %d 个独立文章文件\n",total)
var earliest,latest string;byYear:=map[string]int{};byMonth:=map[string]int{};byDay:=map[string]int{};byWeekday:=map[string]int{};missingDate:=0;dateArticles:=map[string][]int{};tagCount:=map[string]int{};untagged:=0;tagCountDist:=map[string]int{"1":0,"2":0,"3":0,"4+":0};allStats:=map[string]int{};missingAll:=0;allByYear:=map[string]map[string]int{};totalBytes:=0;minBytes,maxBytes:=-1,-1;minTitleLen,maxTitleLen:=-1,-1;titleMissing,titleTotalLen:=0,0;titleDup:=map[string][]int{};titlePrefix:=map[string]int{"中文":0,"英文":0,"数字":0,"其他":0};fieldMissing:=map[string]int{"title":0,"date":0,"tags":0,"all":0,"content":0};featCode,featImage,featMath,featTable,featMermaid,featLink:=0,0,0,0,0,0;sizeBuckets:=map[string]int{"<1KB":0,"1-5KB":0,"5-20KB":0,">20KB":0};longestId,shortestId:=0,0;longestTitle,shortestTitle:="",""
for _,a:=range sorted{id,_:=a["id"].(int);title:=getStringField(a,"title","");if title==""{titleMissing++;fieldMissing["title"]++}else{tl:=utf8.RuneCountInString(title);titleDup[title]=append(titleDup[title],id);titleTotalLen+=tl;if minTitleLen<0||tl<minTitleLen{minTitleLen=tl};if maxTitleLen<0||tl>maxTitleLen{maxTitleLen=tl};r,_:=utf8.DecodeRuneInString(title);switch{case unicode.Is(unicode.Han,r):titlePrefix["中文"]++;case unicode.IsLetter(r):titlePrefix["英文"]++;case unicode.IsDigit(r):titlePrefix["数字"]++;default:titlePrefix["其他"]++}};date:=getStringField(a,"date","");if date==""{missingDate++;fieldMissing["date"]++}else{if earliest==""||date<earliest{earliest=date};if latest==""||date>latest{latest=date};if len(date)>=4{byYear[date[:4]]++};if len(date)>=7{byMonth[date[:7]]++};if len(date)>=10{byDay[date[:10]]++;dateArticles[date[:10]]=append(dateArticles[date[:10]],id);if t,e:=parseDate(date);e==nil{byWeekday[t.Weekday().String()]++}}};tags:=getTagsField(a);if len(tags)==0{untagged++;fieldMissing["tags"]++}else{var names []string;for _,t:=range tags{if s,ok:=t.(string);ok&&s!=""{tagCount[s]++;names=append(names,s)}};switch len(names){case 0:fieldMissing["tags"]++;case 1:tagCountDist["1"]++;case 2:tagCountDist["2"]++;case 3:tagCountDist["3"]++;default:tagCountDist["4+"]++}};if av,ok:=a["all"];ok{s:=normalizeAll(av);if s==""{missingAll++;fieldMissing["all"]++}else{allStats[s]++;if len(date)>=4{y:=date[:4];if allByYear[y]==nil{allByYear[y]=map[string]int{}};allByYear[y][s]++}}}else{missingAll++;fieldMissing["all"]++};content:=getStringField(a,"content","");if content==""{fieldMissing["content"]++};by:=len(content);totalBytes+=by;if minBytes<0||by<minBytes{minBytes=by;shortestId=id;shortestTitle=title};if maxBytes<0||by>maxBytes{maxBytes=by;longestId=id;longestTitle=title};switch{case by<1024:sizeBuckets["<1KB"]++;case by<5120:sizeBuckets["1-5KB"]++;case by<20480:sizeBuckets["5-20KB"]++;default:sizeBuckets[">20KB"]++};if strings.Count(content,"```")>=2{featCode++};if strings.Contains(content,"!["){featImage++};if strings.Contains(content,"$"){featMath++};if strings.Count(content,"| ---")>0{featTable++};if strings.Contains(content,"```mermaid"){featMermaid++};if strings.Count(content,"](")>0{featLink++}}
dateSet:=map[string]bool{};var uniqueDates []time.Time;for _,a:=range sorted{d:=getStringField(a,"date","");if d==""{continue};if t,e:=parseDate(d);e==nil{key:=t.Format("2006-01-02");if!dateSet[key]{dateSet[key]=true;uniqueDates=append(uniqueDates,t)}}};sort.Slice(uniqueDates,func(i,j int)bool{return uniqueDates[i].Before(uniqueDates[j])});longestGapDays:=0;var longestGapFrom,longestGapTo string;for i:=1;i<len(uniqueDates);i++{gap:=int(uniqueDates[i].Sub(uniqueDates[i-1]).Hours()/24);if gap>longestGapDays{longestGapDays=gap;longestGapFrom=uniqueDates[i-1].Format("2006-01-02");longestGapTo=uniqueDates[i].Format("2006-01-02")}};currentStreak:=0;if len(uniqueDates)>0{currentStreak=1;for i:=len(uniqueDates)-1;i>0;i--{gap:=int(uniqueDates[i].Sub(uniqueDates[i-1]).Hours()/24);if gap<=1{currentStreak++}else{break}}}
var dateDups []map[string]interface{};for k,ids:=range dateArticles{if len(ids)>1{dateDups=append(dateDups,map[string]interface{}{"date":k,"ids":ids})}};sort.Slice(dateDups,func(i,j int)bool{return len(dateDups[i]["ids"].([]int))>len(dateDups[j]["ids"].([]int))})
pairCount:=map[string]int{};for _,a:=range sorted{tags:=getTagsField(a);var names []string;for _,t:=range tags{if s,ok:=t.(string);ok&&s!=""{names=append(names,s)}};if len(names)<2{continue};sort.Strings(names);for i:=0;i<len(names);i++{for j:=i+1;j<len(names);j++{pairCount[names[i]+" + "+names[j]]++}}};type kv struct{K string;V int};var topPairs []kv;for k,v:=range pairCount{topPairs=append(topPairs,kv{k,v})};sort.Slice(topPairs,func(i,j int)bool{return topPairs[i].V>topPairs[j].V});pairLimit:=20;if len(topPairs)<pairLimit{pairLimit=len(topPairs)};var pairList []map[string]interface{};for i:=0;i<pairLimit;i++{pairList=append(pairList,map[string]interface{}{"pair":topPairs[i].K,"count":topPairs[i].V})}
var tagList []map[string]interface{};for k,v:=range tagCount{tagList=append(tagList,map[string]interface{}{"name":k,"count":v})};sort.Slice(tagList,func(i,j int)bool{a,b:=tagList[i]["count"].(int),tagList[j]["count"].(int);if a!=b{return a>b};return tagList[i]["name"].(string)<tagList[j]["name"].(string)})
var byYearList []map[string]interface{};for k,v:=range byYear{byYearList=append(byYearList,map[string]interface{}{"year":k,"count":v})};sort.Slice(byYearList,func(i,j int)bool{return byYearList[i]["year"].(string)<byYearList[j]["year"].(string)})
var byMonthList []map[string]interface{};for k,v:=range byMonth{byMonthList=append(byMonthList,map[string]interface{}{"month":k,"count":v})};sort.Slice(byMonthList,func(i,j int)bool{return byMonthList[i]["month"].(string)<byMonthList[j]["month"].(string)})
var byDayList []map[string]interface{};for k,v:=range byDay{byDayList=append(byDayList,map[string]interface{}{"day":k,"count":v})};sort.Slice(byDayList,func(i,j int)bool{return byDayList[i]["day"].(string)<byDayList[j]["day"].(string)})
var byWeekdayList []map[string]interface{};weekOrder:=[]string{"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};weekNames:=map[string]string{"Monday":"周一","Tuesday":"周二","Wednesday":"周三","Thursday":"周四","Friday":"周五","Saturday":"周六","Sunday":"周日"};for _,w:=range weekOrder{byWeekdayList=append(byWeekdayList,map[string]interface{}{"key":w,"label":weekNames[w],"count":byWeekday[w]})}
var dupList []map[string]interface{};for k,ids:=range titleDup{if len(ids)>1{dupList=append(dupList,map[string]interface{}{"title":k,"ids":ids})}};sort.Slice(dupList,func(i,j int)bool{return len(dupList[i]["ids"].([]int))>len(dupList[j]["ids"].([]int))})
var distinctAll []string;for k:=range allStats{distinctAll=append(distinctAll,k)};sort.Strings(distinctAll)
var allByYearList []map[string]interface{};for y,m:=range allByYear{allByYearList=append(allByYearList,map[string]interface{}{"year":y,"values":m})};sort.Slice(allByYearList,func(i,j int)bool{return allByYearList[i]["year"].(string)<allByYearList[j]["year"].(string)})
recentN:=RECENT_N;if total<recentN{recentN=total};var recentList,oldestList []map[string]interface{};for i:=0;i<recentN;i++{a:=sorted[i];recentList=append(recentList,map[string]interface{}{"id":a["id"],"title":getStringField(a,"title","无标题"),"date":getStringField(a,"date","")})};for i:=total-1;i>=total-recentN;i--{a:=sorted[i];oldestList=append(oldestList,map[string]interface{}{"id":a["id"],"title":getStringField(a,"title","无标题"),"date":getStringField(a,"date","")})}
avgTitle:=0;if total-titleMissing>0{avgTitle=titleTotalLen/(total-titleMissing)};avgBytes:=0;if total>0{avgBytes=totalBytes/total};span:=spanDays(earliest,latest)
meta:=map[string]interface{}{"schemaVersion":SCHEMA_VERSION,"generatedAt":time.Now().UTC().Format(time.RFC3339),"source":inputFile,"total":total,"totalPages":totalPages,"pageSize":PAGE_SIZE,"sort":map[string]interface{}{"by":"date","order":"desc"},"raw":map[string]interface{}{"total":len(rawArticles),"active":total,"deleted":deletedCount},"date":map[string]interface{}{"earliest":earliest,"latest":latest,"spanDays":span,"byYear":byYearList,"byMonth":byMonthList,"byDay":byDayList,"byWeekday":byWeekdayList,"missing":missingDate,"duplicates":dateDups,"uniqueDays":len(uniqueDates),"longestGap":map[string]interface{}{"days":longestGapDays,"from":longestGapFrom,"to":longestGapTo},"currentStreak":currentStreak},"tags":map[string]interface{}{"unique":len(tagList),"untagged":untagged,"list":tagList,"byCount":tagCountDist,"topPairs":pairList},"all":map[string]interface{}{"values":allStats,"distinct":distinctAll,"missing":missingAll,"byYear":allByYearList},"content":map[string]interface{}{"totalBytes":totalBytes,"avgBytes":avgBytes,"minBytes":minBytes,"maxBytes":maxBytes,"sizeBuckets":sizeBuckets,"longest":map[string]interface{}{"id":longestId,"title":longestTitle,"bytes":maxBytes},"shortest":map[string]interface{}{"id":shortestId,"title":shortestTitle,"bytes":minBytes}},"features":map[string]interface{}{"codeBlocks":featCode,"images":featImage,"math":featMath,"tables":featTable,"mermaid":featMermaid,"links":featLink},"titles":map[string]interface{}{"missing":titleMissing,"avgLength":avgTitle,"minLength":minTitleLen,"maxLength":maxTitleLen,"duplicates":dupList,"prefix":titlePrefix},"fields":map[string]interface{}{"missing":fieldMissing},"recent":recentList,"oldest":oldestList,"pages":pageIndex,"articles":articleIndex,"files":map[string]interface{}{"all":"all.json","archive":"archive.json","meta":"meta.json","pages":pageFiles,"articles":articleFiles}}
if err:=writeJSON(filepath.Join(outputDir,"meta.json"),meta);err!=nil{fmt.Fprintf(os.Stderr,"写入 meta.json 失败: %v\n",err);os.Exit(1)};fmt.Printf("生成 meta.json (总页数 %d，标签 %d，all 种类 %d，结构特征 代码%d/图%d/公式%d/表%d/流程图%d/链接%d)\n",totalPages,len(tagList),len(distinctAll),featCode,featImage,featMath,featTable,featMermaid,featLink)}
func normalizeAll(v interface{})string{switch x:=v.(type){case string:return x;case float64:if x==float64(int64(x)){return fmt.Sprintf("%d",int64(x))};return fmt.Sprintf("%v",x);case bool:if x{return "1"};return "0";case nil:return "";default:return fmt.Sprintf("%v",x)}}
func getAllField(m map[string]interface{})string{if v,ok:=m["all"];ok{return normalizeAll(v)};return ""}
func getStringField(m map[string]interface{},key,def string)string{if v,ok:=m[key];ok{if s,ok:=v.(string);ok&&s!=""{return s}};return def}
func getTagsField(m map[string]interface{})[]interface{}{if v,ok:=m["tags"];ok{if t,ok:=v.([]interface{});ok{return t}};return []interface{}{}}
func parseDate(s string)(time.Time,error){if t,e:=time.Parse("2006-01-02",s);e==nil{return t,nil};if t,e:=time.Parse("2006-01-02 15:04:05",s);e==nil{return t,nil};if t,e:=time.Parse(time.RFC3339,s);e==nil{return t,nil};return time.Time{},fmt.Errorf("invalid date")}
func spanDays(a,b string)int{if a==""||b==""{return 0};t1,e1:=parseDate(a);t2,e2:=parseDate(b);if e1!=nil||e2!=nil{return 0};d:=t2.Sub(t1).Hours()/24;if d<0{d=-d};return int(d)}
func writeJSON(fn string,d interface{})error{b,e:=json.MarshalIndent(d,"","  ");if e!=nil{return e};return os.WriteFile(fn,b,0644)}
